class _SpinWheelPainter extends CustomPainter{
  @override void paint(Canvas canvas,Size size){final center=Offset(size.width/2,size.height/2);final radius=(min(size.width,size.height)/2).toDouble();const sweep=2*pi/8;final colors=[_econPink,const Color(0xFF4C3151),_econGold,const Color(0xFF24434D),_econBlue,const Color(0xFF49304A),const Color(0xFF23A989),const Color(0xFF563A24)];final labels=['200\nCOINS','500\nCOINS','1K\nCOINS','5K\nCOINS','5\nDIAMONDS','20\nDIAMONDS','50\nDIAMONDS','20K\nJACKPOT'];for(var i=0;i<8;i++){final start=-pi/2+i*sweep;canvas.drawArc(Rect.fromCircle(center:center,radius:radius),start,sweep,true,Paint()..color=colors[i]..style=PaintingStyle.fill);canvas.drawArc(Rect.fromCircle(center:center,radius:radius),start,sweep,true,Paint()..color=Colors.white.withOpacity(.6)..style=PaintingStyle.stroke..strokeWidth=1.4);final angle=start+sweep/2;final pos=center+Offset(cos(angle)*radius*.64,sin(angle)*radius*.64);canvas.save();canvas.translate(pos.dx,pos.dy);canvas.rotate(angle+pi/2);final text=TextPainter(text:TextSpan(text:labels[i],style:TextStyle(color:Colors.white,fontSize:i==7?9:8,fontWeight:FontWeight.w900,shadows:const [Shadow(color:Colors.black,blurRadius:3)])),textAlign:TextAlign.center,textDirection:TextDirection.ltr)..layout(maxWidth:55);text.paint(canvas,Offset(-text.width/2,-text.height/2));canvas.restore();}}
  @override bool shouldRepaint(covariant _SpinWheelPainter oldDelegate)=>false;
}

